from urllib.parse import urlsplit, urlunsplit, parse_qsl


def _host_matches(host: str | None, match_value: str) -> bool:
    """Check exact host or strict subdomain matching."""
    if host is None:
        return False

    host = host.casefold()
    match_value = match_value.casefold()

    if match_value.startswith("*."):
        base = match_value[2:]
        # The base domain itself must not match.
        return host != base and host.endswith("." + base)

    return host == match_value


def _replace_host_preserving_port(parsed, new_host: str) -> str:
    """Replace only the hostname while preserving userinfo and port."""
    netloc = parsed.netloc

    # Separate user information from host/port.
    if "@" in netloc:
        userinfo, hostport = netloc.rsplit("@", 1)
        userinfo += "@"
    else:
        userinfo = ""
        hostport = netloc

    # Preserve the original port text.
    port_suffix = ""
    if hostport.startswith("["):
        # IPv6 host
        closing_bracket = hostport.find("]")
        if closing_bracket != -1:
            port_suffix = hostport[closing_bracket + 1 :]
    elif hostport.count(":") == 1:
        # Regular hostname with an optional port
        _, possible_port = hostport.rsplit(":", 1)
        if possible_port:
            port_suffix = ":" + possible_port

    # IPv6 replacement hosts need brackets in a netloc.
    if ":" in new_host and not new_host.startswith("["):
        new_host = f"[{new_host}]"

    return userinfo + new_host + port_suffix


def apply_rewrite_rules(rules, urls):
    """
    Apply the first matching rewrite rule to each URL.

    Returns a list containing rewritten URLs or None for blocked URLs.
    """
    results = []

    for url in urls:
        parsed = urlsplit(url)
        rewritten = url

        for rule in rules:
            match_type = rule["match_type"]
            match_value = rule["match_value"]
            action = rule["action"]

            matched = False

            if match_type == "path_prefix":
                matched = parsed.path.startswith(match_value)

            elif match_type == "host":
                matched = _host_matches(parsed.hostname, match_value)

            elif match_type == "query_param":
                query_params = parse_qsl(
                    parsed.query,
                    keep_blank_values=True,
                )
                matched = any(name == match_value for name, _ in query_params)

            else:
                raise ValueError(f"Unknown match_type: {match_type}")

            if not matched:
                continue

            # The first matching rule always ends processing for this URL.
            if action == "block":
                rewritten = None
            elif action == "strip_prefix":
                prefix = rule["action_value"]
                new_path = parsed.path

                if new_path.startswith(prefix):
                    new_path = new_path[len(prefix):]

                if new_path == "":
                    new_path = "/"

                rewritten = urlunsplit(parsed._replace(path=new_path))

            elif action == "redirect_host":
                new_netloc = _replace_host_preserving_port(
                    parsed,
                    rule["action_value"],
                )
                rewritten = urlunsplit(parsed._replace(netloc=new_netloc))

            elif action == "add_query_param":
                addition = rule["action_value"]
                new_query = (
                    f"{parsed.query}&{addition}"
                    if parsed.query
                    else addition
                )
                rewritten = urlunsplit(parsed._replace(query=new_query))

            else:
                raise ValueError(f"Unknown action: {action}")

            break

        results.append(rewritten)

    return results
